const audio={enabled:false,ctx:null,init(){try{this.ctx??=new AudioContext();if(this.ctx.state==='suspended')this.ctx.resume()}catch{}},tone(f,t=.14,type='sine',v=.06){if(!this.enabled||!this.ctx)return;let c=this.ctx,o=c.createOscillator(),g=c.createGain();o.type=type;o.frequency.setValueAtTime(f,c.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(30,f*.45),c.currentTime+t);g.gain.setValueAtTime(v,c.currentTime);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+t);o.connect(g);g.connect(c.destination);o.start();o.stop(c.currentTime+t)},boom(){if(!this.enabled||!this.ctx)return;let c=this.ctx,b=c.createBuffer(1,c.sampleRate*.45,c.sampleRate),d=b.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=(Math.random()*2-1)*Math.pow(1-i/d.length,2);let n=c.createBufferSource(),g=c.createGain(),f=c.createBiquadFilter();n.buffer=b;f.type='lowpass';f.frequency.value=650;g.gain.value=.27;n.connect(f);f.connect(g);g.connect(c.destination);n.start();this.tone(85,.4,'triangle',.12)}};
function toast(text,sec=2.8){$('toast').textContent=text;$('toast').classList.add('show');toastTime=sec}
