function setupLobby(){inLobby=true;held.clear();modal=null;document.body.classList.remove('playing');$('lobby').hidden=false;$('hud').hidden=true;$('pause').hidden=true;$('modalShade').hidden=true;$('arsenal').hidden=true;options.theme=clamp(options.theme,0,THEMES.length-1);game=new Game({...options,seed:THEMES[options.theme].seed});game.drain();renderer.setGame(game,true);applyTheme();$('resume').hidden=!read(SAVE,null);$('record').textContent=`대전 ${record.played}회 · AI전 승리 ${record.wins}회`;}
