function handleEvents(){for(let e of game.drain()){renderer.event(e);if(e.type==='turn'){$('overview').textContent='전장 보기 ⌖';let u=game.units[e.id];$('turnBanner').querySelector('small').textContent=game.human()?'YOUR TURN':'OPPONENT TURN';$('turnBanner').querySelector('strong').textContent=u.name+', 출동!';$('turnBanner').querySelector('span').textContent=(game.team?'코랄 원정대':'블루 탐험대')+' · 준비 3초';$('turnBanner').classList.add('show');bannerTime=2.7;$('arsenal').hidden=true;audio.tone(game.team?300:420,.23);saveBattle()}else if(e.type==='action'){toast(game.human()?'이동하고 조준하세요. 행동 시간 '+game.options.turnTime+'초':'상대가 바람을 읽고 있어요…',2);saveBattle()}else if(e.type==='fire'){audio.tone(180,.17,'sawtooth',.07);toast('발사! 4초 동안 대피할 수 있어요.',2);$('arsenal').hidden=true;if(navigator.vibrate)navigator.vibrate(18)}else if(e.type==='explosion'){audio.boom();if(navigator.vibrate)navigator.vibrate([25,20,35])}else if(e.type==='jump')audio.tone(340,.13,'triangle');else if(e.type==='bounce')audio.tone(130,.04,'triangle',.025);else if(e.type==='heal'){audio.tone(700,.3);toast('체력을 30까지 회복했습니다.');}else if(e.type==='timeout')toast('시간 종료! 다음 팀에게 차례를 넘깁니다.');else if(e.type==='sudden')toast('서든 데스! 해수면이 서서히 올라옵니다.',4);else if(e.type==='message')toast(e.text);else if(e.type==='end')finishGame();} }
