function campaignMenu(){const cleared=progress.cleared;$('campaignProgress').textContent=cleared.length+'/12 클리어 · '+Critters.unlockedFor(cleared).length+'/16 무기·도구';const buttons=Critters.STAGES.map(s=>{const locked=s.id>0&&!cleared.includes(s.id-1),b=document.createElement('button');b.className='stage-card'+(locked?' locked':'');b.disabled=locked;const canvas=document.createElement('canvas');canvas.width=280;canvas.height=100;const ctx=canvas.getContext('2d'),preview=new Game({theme:s.theme,layout:s.layout,seed:s.seed}),theme=THEMES[s.theme],gr=ctx.createLinearGradient(0,0,0,100);gr.addColorStop(0,theme.sky[0]);gr.addColorStop(1,theme.sky[1]);ctx.fillStyle=gr;ctx.fillRect(0,0,280,100);ctx.fillStyle=theme.earth;ctx.beginPath();ctx.moveTo(0,100);for(let x=0;x<1600;x+=8)ctx.lineTo(x/1600*280,preview.heights[x]/900*100);ctx.lineTo(280,100);ctx.fill();ctx.fillStyle=theme.sea;ctx.fillRect(0,88,280,12);b.append(canvas);for(const [tag,text] of [['b',String(s.id+1).padStart(2,'0')+' · '+s.name],['small',locked?'이전 스테이지를 먼저 클리어하세요':s.tip],['em','보상 · '+WEAPONS[s.unlock].name],['small','★'.repeat(progress.stars[s.id]||0)+'☆'.repeat(3-(progress.stars[s.id]||0))]]){const el=document.createElement(tag);el.textContent=text;b.append(el);}b.onclick=()=>launchStage(s.id);return b;});$('stageGrid').replaceChildren(...buttons);showModal('campaignPanel');}
$('campaignOpen').onclick=campaignMenu;$('campaignClose').onclick=hideModal;
const mapSelect=document.createElement('select');mapSelect.ariaLabel='자유 대전 지도';for(const s of Critters.STAGES){const o=document.createElement('option');o.value=s.id;o.textContent=String(s.id+1).padStart(2,'0')+' · '+s.name;mapSelect.append(o);}mapSelect.value=options.theme;mapSelect.onchange=()=>{delete options.stage;options.layout=+mapSelect.value;options.theme=+mapSelect.value;applyTheme();game=new Game({...options,seed:THEMES[options.theme].seed});game.drain();renderer.setGame(game,true);};$('maps').replaceChildren(mapSelect);

$('start').onclick=()=>{delete options.stage;delete options.layout;startGame()};$('resume').onclick=()=>{try{let data=read(SAVE,null),g=Game.restore(data);if(!g)throw Error('invalid save');startGame(g)}catch{try{localStorage.removeItem(SAVE)}catch{}$('resume').hidden=true;alert('저장된 전투를 읽을 수 없어 새 전투로 시작합니다.');startGame()}};
document.querySelectorAll('[data-value]').forEach(b=>b.onclick=()=>{options.mode=b.dataset.value;applyTheme()});document.querySelectorAll('[data-theme]').forEach(b=>b.onclick=()=>{options.theme=+b.dataset.theme;applyTheme();game=new Game({...options,seed:THEMES[options.theme].seed});game.drain();renderer.setGame(game,true)});$('difficulty').onchange=()=>{options.difficulty=$('difficulty').value;applyTheme()};$('turnTime').onchange=()=>{options.turnTime=+$('turnTime').value;applyTheme()};
$('angle').oninput=$('power').oninput=()=>{game.setAim(+$('angle').value,+$('power').value);$('angleValue').textContent=Math.round(game.angle)+'°';$('powerValue').textContent=Math.round(game.power)+'%'};$('fire').onclick=()=>{audio.init();game.fire();handleEvents();sync()};$('jump').onclick=()=>{game.jump();handleEvents();sync()};for(let id of ['left','right']){$(id).onpointerdown=e=>{if(!game.canMove())return;e.preventDefault();held.add(id);$(id).setPointerCapture(e.pointerId)};for(let ev of ['pointerup','pointercancel','lostpointercapture'])$(id).addEventListener(ev,()=>held.delete(id))}
$('loadout').onclick=weaponMenu;$('closeArsenal').onclick=()=>$('arsenal').hidden=true;$('pause').onclick=()=>showModal('pauseMenu');$('continue').onclick=hideModal;$('restart').onclick=()=>startGame();$('toLobby').onclick=()=>{if(!inLobby)saveBattle();hideModal();setupLobby()};$('rematch').onclick=()=>startGame();$('resultLobby').onclick=()=>{hideModal();setupLobby()};$('help').onclick=()=>showModal('guide');$('closeGuide').onclick=hideModal;$('brand').onclick=e=>{e.preventDefault();if(inLobby)return;showModal('pauseMenu')};$('overview').onclick=()=>{renderer.overview=!renderer.overview;renderer.manual=0;$('overview').textContent=renderer.overview?'병사로 돌아가기 ⌖':'전장 보기 ⌖'};$('audio').onclick=()=>{audio.init();audio.enabled=!audio.enabled;$('audio').style.opacity=audio.enabled?'1':'.5';$('audio').title=$('audio').ariaLabel=audio.enabled?'소리 끄기':'소리 켜기';audio.tone(550)};
