document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if(e.key==='Escape'){if(modal==='pauseMenu')hideModal();else if(!inLobby&&!modal)showModal('pauseMenu');return}if(inLobby||modal)return;let k=e.key.toLowerCase();if(['a','d','w','arrowleft','arrowright','arrowup',' '].includes(k))e.preventDefault();if(k==='a'||k==='arrowleft')held.add('left');if(k==='d'||k==='arrowright')held.add('right');if((k==='w'||k==='arrowup')&&!e.repeat)game.jump();if(k===' '&&!e.repeat){game.fire();handleEvents();sync()}if(['1','2','3','4'].includes(k)){game.select(+k-1);sync()}});document.addEventListener('keyup',e=>{if(['a','arrowleft'].includes(e.key.toLowerCase()))held.delete('left');if(['d','arrowright'].includes(e.key.toLowerCase()))held.delete('right')});
let drag=null;$('scene').onpointerdown=e=>{if(inLobby||modal)return;drag={id:e.pointerId,x:e.clientX,y:e.clientY,startX:e.clientX,startY:e.clientY,moved:false};$('scene').setPointerCapture(e.pointerId)};$('scene').onpointermove=e=>{if(!drag||drag.id!==e.pointerId)return;let dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)>5)drag.moved=true;if(drag.moved)renderer.pan(dx,dy);drag.x=e.clientX;drag.y=e.clientY};$('scene').onpointerup=e=>{if(!drag)return;if(!drag.moved){let p=renderer.worldPoint(e.clientX,e.clientY);let u=game.alive().find(u=>Math.hypot(u.x-p.x,u.y-p.y)<55);if(u){renderer.focus(u);renderer.manual=4}}drag=null};$('scene').onpointercancel=()=>drag=null;
